import{_ as e,c as o,o as a,ag as r}from"./chunks/framework._xRlcm3f.js";const h=JSON.parse('{"title":"Jvue 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/metaweblog-jvue.md","filePath":"platforms/metaweblog-jvue.md","lastUpdated":1790228279000}'),l={name:"platforms/metaweblog-jvue.md"};function d(i,t,s,n,g,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="jvue-配置指南" tabindex="-1">Jvue 配置指南 <a class="header-anchor" href="#jvue-配置指南" aria-label="Permalink to &quot;Jvue 配置指南&quot;">​</a></h1><p>通过 <strong>MetaWeblog XML-RPC</strong> 协议把思源笔记发布到 <strong>Jvue</strong> 博客。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可访问的 <strong>Jvue</strong> 博客站点，并开启 MetaWeblog 接口。</li><li>站点的 <strong>MetaWeblog API 端点地址</strong>（Jvue 需显式填写，不由首页推导）。</li><li>Jvue 后台的<strong>登录用户名与登录密码</strong>（MetaWeblog 按账号密码鉴权，不使用 Token）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>博客首页</td><td>你的 Jvue 博客首页地址，如 <code>https://blog.example.com</code></td></tr><tr><td>API 地址</td><td>站点的 MetaWeblog 端点地址（需手动填写，不由首页推导）</td></tr><tr><td>用户名</td><td>Jvue 后台的登录用户名</td></tr><tr><td>密码</td><td>Jvue 后台的登录密码</td></tr><tr><td>查看文章链接</td><td>固定 <code>/post/[postid].html</code>，不支持修改</td></tr><tr><td>发布格式</td><td>正文提交格式，默认 Markdown，保持默认即可</td></tr><tr><td>图床</td><td>按需选择「当前平台」「PicGo 强烈推荐」或「不使用」</td></tr></tbody></table><blockquote><p>Jvue 通过 MetaWeblog 发布时不暴露分类目录选择，因此配置页<strong>没有「发布目录」行</strong>。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 站点连通性与账号校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Jvue → 发布。文章提交到站点。</li><li>「查看文章」按 <code>/post/[postid].html</code> 打开。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证失败或提示账号错误</strong>：确认用户名是后台登录用户名、密码是登录密码（不使用 Token）；再确认 API 地址是站点真正提供 MetaWeblog 的端点。</li><li><strong>API 地址要不要手动填</strong>：要。Jvue 的 API 地址需要手动填入站点提供 XML-RPC 的接口地址。</li><li><strong>为什么没有「发布目录」</strong>：该协议发布时不暴露分类目录选择，文章直接进入站点。</li><li><strong>查看链接能改吗</strong>：不能，固定为 <code>/post/[postid].html</code>。</li><li><strong>图片要怎么发布</strong>：按需选择图床。「当前平台」随文章提交到站点；「PicGo 强烈推荐」先在上层设置里配置好 PicGo；「不使用」则按原图地址引用。</li><li><strong>更新与删除</strong>：点「更新」会覆盖站点上的同一篇文章；「删除」会移除该文章。</li></ul>',11)])])}const b=e(l,[["render",d]]);export{h as __pageData,b as default};
